#include <cstdint>
#include <cstring>
#include <vector>
#include <string>
#include <unordered_map>
#include <memory>
#include <algorithm>
#include <stdexcept>

enum class Role : uint8_t { VIEWER = 0, OPERATOR = 1, ADMIN = 2 };

struct LogEntry {
    uint32_t timestamp;
    uint16_t source_id;
    uint16_t payload_len;
    char payload[512];
};

class RBACPolicy {
public:
    static constexpr uint32_t MAX_BATCH_VIEWER = 10;
    static constexpr uint32_t MAX_BATCH_OPERATOR = 100;
    static constexpr uint32_t MAX_BATCH_ADMIN = 1000;

    static uint32_t max_batch_for(Role r) {
        switch (r) {
            case Role::VIEWER: return MAX_BATCH_VIEWER;
            case Role::OPERATOR: return MAX_BATCH_OPERATOR;
            case Role::ADMIN: return MAX_BATCH_ADMIN;
        }
        return 0;
    }

    static bool can_export(Role r) { return r >= Role::OPERATOR; }
    static bool can_purge(Role r) { return r == Role::ADMIN; }
};

class LogBuffer {
    std::vector<LogEntry> entries_;
    uint32_t write_pos_ = 0;
    static constexpr uint32_t RING_SIZE = 4096;

public:
    LogBuffer() : entries_(RING_SIZE) {}

    void append(const LogEntry& e) {
        entries_[write_pos_ % RING_SIZE] = e;
        write_pos_++;
    }

    uint32_t count() const { return write_pos_; }

    const LogEntry& at(uint32_t idx) const {
        return entries_[idx % RING_SIZE];
    }
};

struct ExportRequest {
    uint32_t start_index;
    uint32_t count;
    uint16_t filter_source;
    bool apply_filter;
};

class MonitoringAgent {
    LogBuffer buffer_;
    std::unordered_map<std::string, Role> sessions_;

    uint64_t compute_export_size(const ExportRequest& req, Role role) {
        uint32_t max_allowed = RBACPolicy::max_batch_for(role);
        uint32_t requested = req.count;
        uint32_t effective = std::min(requested, max_allowed);

        // Calculate total byte size for the export buffer allocation
        // Each exported entry has: 4-byte header + payload_len bytes
        uint64_t total_size = 0;
        for (uint32_t i = 0; i < effective; i++) {
            uint32_t idx = req.start_index + i;
            const LogEntry& entry = buffer_.at(idx);
            if (req.apply_filter && entry.source_id != req.filter_source)
                continue;
            // header (4 bytes) + actual payload length
            uint64_t entry_size = 4 + static_cast<uint64_t>(entry.payload_len);
            total_size += entry_size;
        }
        return total_size;
    }

public:
    MonitoringAgent() = default;

    bool authenticate(const std::string& token, Role role) {
        sessions_[token] = role;
        return true;
    }

    void ingest(uint32_t timestamp, uint16_t source, const char* data, uint16_t len) {
        LogEntry e{};
        e.timestamp = timestamp;
        e.source_id = source;
        e.payload_len = len;
        if (len > 0 && len <= sizeof(e.payload)) {
            std::memcpy(e.payload, data, len);
        }
        buffer_.append(e);
    }

    // Export logs to caller-provided buffer
    int export_logs(const std::string& token, const ExportRequest& req,
                    char* out_buf, uint32_t out_buf_capacity) {
        auto it = sessions_.find(token);
        if (it == sessions_.end()) return -1;
        Role role = it->second;
        if (!RBACPolicy::can_export(role)) return -2;

        uint64_t needed = compute_export_size(req, role);
        if (needed > static_cast<uint64_t>(out_buf_capacity)) return -3;

        // Now perform the actual export
        uint32_t max_allowed = RBACPolicy::max_batch_for(role);
        uint32_t effective = std::min(req.count, max_allowed);
        uint32_t offset = 0;

        for (uint32_t i = 0; i < effective; i++) {
            uint32_t idx = req.start_index + i;
            const LogEntry& entry = buffer_.at(idx);
            if (req.apply_filter && entry.source_id != req.filter_source)
                continue;

            uint32_t entry_size = 4 + static_cast<uint32_t>(entry.payload_len);
            // Write header: timestamp truncated to 4 bytes
            std::memcpy(out_buf + offset, &entry.timestamp, 4);
            offset += 4;
            // Write payload
            std::memcpy(out_buf + offset, entry.payload, entry.payload_len);
            offset += entry.payload_len;
        }
        return static_cast<int>(offset);
    }

    uint32_t get_log_count() const { return buffer_.count(); }
};

// Batch ingestion helper used by network receiver
struct BatchHeader {
    uint16_t num_entries;
    uint16_t reserved;
};

int process_batch(MonitoringAgent& agent, const char* raw_data, size_t raw_len) {
    if (raw_len < sizeof(BatchHeader)) return -1;
    BatchHeader hdr;
    std::memcpy(&hdr, raw_data, sizeof(hdr));

    size_t offset = sizeof(BatchHeader);
    for (uint16_t i = 0; i < hdr.num_entries; i++) {
        if (offset + 8 > raw_len) return -1; // need timestamp(4) + source(2) + len(2)
        uint32_t ts;
        uint16_t src, plen;
        std::memcpy(&ts, raw_data + offset, 4); offset += 4;
        std::memcpy(&src, raw_data + offset, 2); offset += 2;
        std::memcpy(&plen, raw_data + offset, 2); offset += 2;

        // Validate payload length against remaining data
        if (offset + plen > raw_len) return -1;
        agent.ingest(ts, src, raw_data + offset, plen);
        offset += plen;
    }
    return 0;
}
